/* --- JOIN TABLE ---
 *
 * st_type_join[a][b] = narrowest type covering both a and b.
 *
 * Lattice:
 *   #sha ⊂ #h ⊂ #val ⊂ *
 *   #i ⊂ #val ⊂ *
 *   #i, #ipv6 ⊂ #ipaddr ⊂ #val ⊂ *
 *   #w ⊂ #val ⊂ *
 *   #q ⊂ #qs ⊂ #val ⊂ *
 *   #f ⊂ #r ⊂ #path ⊂ *
 *   #p ⊂ #path ⊂ *
 *   #u ⊂ *
 *   #sopt, #lopt ⊂ #opt ⊂ #val ⊂ *
 *   #uuid, #email, #host, #size, #semver, #ts, #env ⊂ #val ⊂ *
 *   #port ⊂ #n ⊂ #val ⊂ *
 *   #hash, #hyp, #method ⊂ #w ⊂ #val ⊂ *
 *   #mac, #cron, #duration, #branch, #image, #pkg, #user, #fp ⊂ #val ⊂ *
 */

